using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Imaging;using RAWSelectionAssistant.ViewModels;using RAWSelectionAssistant.Core.Services.Projects;
namespace RAWSelectionAssistant.Views;
/// <summary>WPF viewing-state host. Shares target/variant identities; not a collage or second library.</summary>
public sealed class StudioViewingTableView:DockPanel
{
 private readonly ReferenceColorWorkspaceViewModel workspace;private readonly Canvas canvas=new(){Width=2400,Height=3600,Background=new SolidColorBrush(Color.FromRgb(28,29,30))};private readonly TextBlock status=new(){TextWrapping=TextWrapping.Wrap,Foreground=Brushes.Gainsboro,Margin=new Thickness(6)};private ViewingFrame? selected;private Point? drag;private FrameworkElement? dragged;private readonly System.Windows.Threading.DispatcherTimer slide=new(){Interval=TimeSpan.FromSeconds(3)};private int slideIndex;private readonly ContentControl detail=new(){Visibility=Visibility.Collapsed,Height=260};private long detailRevision;private CancellationTokenSource? detailCancellation;private bool closed;
 public event Action? ReturnRequested;
 public StudioViewingTableView(ReferenceColorWorkspaceViewModel model)
 {
  workspace=model;Background=new SolidColorBrush(Color.FromRgb(29,29,32));LastChildFill=true;var bar=new WrapPanel();Button Add(string text,Action action){var b=new Button{Content=text,Margin=new Thickness(3),Padding=new Thickness(6,3,6,3)};b.Click+=(_,_)=>action();System.Windows.Automation.AutomationProperties.SetName(b,text);bar.Children.Add(b);return b;}
  Add("固定所选照片/变体",()=>Run(async()=>{workspace.PinSelectedViewingVariants();await RefreshAsync();}));Add("显式重新固定所选",()=>Run(async()=>{workspace.PinSelectedViewingVariants(true);await RefreshAsync();}));Add("移出所选",()=>Run(async()=>{if(selected is not null)workspace.RemoveViewingItem(selected.Item.TargetId,selected.Item.VariantId);await RefreshAsync();}));Add("清空灯箱",()=>Run(async()=>{workspace.ClearViewingPlacements();await RefreshAsync();}));Add("局部放大（代理）",()=>Run(ShowDetailAsync));Add("旋转90°",()=>TransformSelected(1,90));Add("放大",()=>TransformSelected(1.15,0));Add("缩小",()=>TransformSelected(1/1.15,0));Add("比较所选与下一张",()=>Run(CompareAsync));Add("幻灯/停止",()=>{if(slide.IsEnabled)slide.Stop();else{slide.Start();if(workspace.ViewingFrames.Count>0){selected=workspace.ViewingFrames[0];Run(ShowDetailAsync);}}});Add("创意胶片（8位）",()=>Run(async()=>{if(selected is null)throw new InvalidOperationException("先选择固定照片");await workspace.GenerateViewingFilmAsync(selected.Item);await RefreshAsync();}));var spek=Add("SpektraLab（未准入）",()=>{});spek.IsEnabled=false;spek.ToolTip=FilmBackendRegistryV1.Backends.Single(x=>x.Id=="spektralab").Reason;Add("取消任务",()=>{workspace.CancelFilmBackendTask();workspace.CancelViewing();});Add("保存项目",()=>Run(async()=>await workspace.SaveSessionCommand.ExecuteAsync(null)));Add("返回暗室",()=>Run(ReturnToDarkroomAsync));var light=new CheckBox{Content="展示灯光（仅观片）",IsChecked=workspace.ViewingTable.PresentationLight,Margin=new Thickness(6)};light.Checked+=(_,_)=>{workspace.SetViewingLight(true);UpdateLight();};light.Unchecked+=(_,_)=>{workspace.SetViewingLight(false);UpdateLight();};bar.Children.Add(light);SetDock(bar,Dock.Top);Children.Add(bar);SetDock(status,Dock.Top);Children.Add(status);SetDock(detail,Dock.Bottom);Children.Add(detail);Children.Add(new ScrollViewer{Content=canvas,HorizontalScrollBarVisibility=ScrollBarVisibility.Auto,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});
  slide.Tick+=(_,_)=>{if(workspace.ViewingFrames.Count==0)return;selected=workspace.ViewingFrames[slideIndex++%workspace.ViewingFrames.Count];Run(ShowDetailAsync);};Unloaded+=(_,_)=>Close();UpdateLight();
 }
 private void Run(Func<Task> action)=>RunAsync(action);
 private async void RunAsync(Func<Task> action){try{await action();if(!closed)status.Text=workspace.ViewingStatus+" · "+workspace.FilmTaskStatus;}catch(Exception e)when(e is IOException or InvalidOperationException or NotSupportedException or ArgumentException or OperationCanceledException){if(!closed)status.Text=e is OperationCanceledException?"操作已取消":e.Message;}}
 private void UpdateLight()=>canvas.Background=new SolidColorBrush(workspace.ViewingTable.PresentationLight?Color.FromRgb(65,64,59):Color.FromRgb(28,29,30));
 public async Task RefreshAsync(){detailRevision++;detailCancellation?.Cancel();await workspace.PrepareViewingTableAsync();if(closed)return;canvas.Children.Clear();selected=null;detail.Content=null;detail.Visibility=Visibility.Collapsed;foreach(var frame in workspace.ViewingFrames){var border=new Border{Width=210,Height=150,Background=new SolidColorBrush(Color.FromRgb(37,38,39)),BorderBrush=Brushes.Gray,BorderThickness=new Thickness(1),Padding=new Thickness(5),Tag=frame};var panel=new DockPanel();var label=new TextBlock{Text=frame.Item.FrozenVariant.Name,TextTrimming=TextTrimming.CharacterEllipsis,Foreground=Brushes.Gainsboro};SetDock(label,Dock.Bottom);panel.Children.Add(label);panel.Children.Add(new Image{Source=frame.Image,Stretch=Stretch.Uniform,ToolTip=frame.ResolutionLabel});border.Child=panel;ApplyTransform(border,frame.Item);Canvas.SetLeft(border,frame.Item.X);Canvas.SetTop(border,frame.Item.Y);canvas.Children.Add(border);border.MouseLeftButtonDown+=(_,e)=>{selected=frame;drag=e.GetPosition(canvas);dragged=border;border.CaptureMouse();status.Text=frame.ResolutionLabel+" · 固定版本 "+frame.Item.VariantId.ToString("N")[..8];e.Handled=true;};border.MouseMove+=(_,e)=>{if(drag is not{} point||dragged!=border||e.LeftButton!=MouseButtonState.Pressed)return;var next=e.GetPosition(canvas);Canvas.SetLeft(border,Math.Clamp(Canvas.GetLeft(border)+next.X-point.X,0,2200));Canvas.SetTop(border,Math.Clamp(Canvas.GetTop(border)+next.Y-point.Y,0,3400));drag=next;};border.MouseLeftButtonUp+=(_,_)=>{if(dragged==border){var i=CurrentItem(frame.Item);workspace.SetViewingPlacement(i.TargetId,i.VariantId,Canvas.GetLeft(border),Canvas.GetTop(border),i.Scale,i.Rotation);drag=null;dragged=null;border.ReleaseMouseCapture();}};border.MouseWheel+=(_,e)=>{selected=frame;TransformSelected(e.Delta>0?1.1:1/1.1,0);e.Handled=true;};}
  if(workspace.ViewingFrames.Count>0)selected=workspace.ViewingFrames[0];status.Text=workspace.ViewingStatus;
 }
 private ViewingTableItem CurrentItem(ViewingTableItem item)=>workspace.ViewingTable.Items.Single(i=>i.TargetId==item.TargetId&&i.VariantId==item.VariantId);
 private static void ApplyTransform(FrameworkElement element,ViewingTableItem item){var transform=new TransformGroup();transform.Children.Add(new ScaleTransform(item.Scale,item.Scale));transform.Children.Add(new RotateTransform(item.Rotation));element.RenderTransform=transform;element.RenderTransformOrigin=new Point(.5,.5);}
 private void TransformSelected(double scale,double rotate){if(selected is null)return;var item=CurrentItem(selected.Item);var next=item with{Scale=Math.Clamp(item.Scale*scale,.1,8),Rotation=(item.Rotation+rotate)%360};workspace.SetViewingPlacement(item.TargetId,item.VariantId,next.X,next.Y,next.Scale,next.Rotation);foreach(var card in canvas.Children.OfType<FrameworkElement>())if(card.Tag is ViewingFrame frame&&frame.Item.TargetId==item.TargetId&&frame.Item.VariantId==item.VariantId)ApplyTransform(card,next);}
 private async Task ShowDetailAsync(){if(selected is null)return;detailCancellation?.Cancel();detailCancellation?.Dispose();detailCancellation=new();var id=++detailRevision;var frame=selected;var image=await workspace.RenderViewingItemAsync(frame.Item,1600,detailCancellation.Token);if(closed||id!=detailRevision)return;var viewport=new ColorStudioImageViewport{Original=image,Mode="原片",SourcePixelSize=new Size(image.PixelWidth,image.PixelHeight)};viewport.MouseWheel+=(_,e)=>{viewport.State.ZoomAbout(e.GetPosition(viewport),e.Delta>0?1.2:1/1.2);e.Handled=true;};Point? detailPan=null;viewport.MouseLeftButtonDown+=(_,e)=>{if(e.ClickCount==2){viewport.State.Fit();e.Handled=true;return;}detailPan=e.GetPosition(viewport);viewport.CaptureMouse();e.Handled=true;};viewport.MouseMove+=(_,e)=>{if(detailPan is{} start&&e.LeftButton==MouseButtonState.Pressed){var next=e.GetPosition(viewport);viewport.State.PanBy(next-start);detailPan=next;}};viewport.MouseLeftButtonUp+=(_,_)=>{detailPan=null;viewport.ReleaseMouseCapture();};viewport.LostMouseCapture+=(_,_)=>detailPan=null;var root=new DockPanel();var label=new TextBlock{Text=$"局部放大：实际代理 {image.PixelWidth}×{image.PixelHeight}；不是原图1:1细节",Foreground=Brushes.Gainsboro};SetDock(label,Dock.Top);root.Children.Add(label);root.Children.Add(viewport);detail.Content=root;detail.Visibility=Visibility.Visible;}
 private Task CompareAsync(){if(selected is null||workspace.ViewingFrames.Count<2)return Task.CompletedTask;var index=workspace.ViewingFrames.ToList().IndexOf(selected);var other=workspace.ViewingFrames[(index+1)%workspace.ViewingFrames.Count];var compare=new StudioSharedComparisonView();compare.SetFrames(new[]{selected,other}.Select(f=>new R53VariantFrame(f.Item.VariantId,f.Item.FrozenVariant.Name,f.Image){SourceTargetId=f.Item.TargetId,SourceVersionId=f.Item.VariantId,SourceHash=f.Item.SourceHash}).ToArray());detail.Content=compare;detail.Visibility=Visibility.Visible;return Task.CompletedTask;}
 private async Task ReturnToDarkroomAsync(){if(selected is not null)await workspace.ReturnViewingToDarkroomAsync(selected.Item);Close();ReturnRequested?.Invoke();}
 public void Close(){if(closed)return;closed=true;slide.Stop();detailRevision++;detailCancellation?.Cancel();detailCancellation?.Dispose();detailCancellation=null;workspace.CancelFilmBackendTask();workspace.ReleaseViewing();canvas.Children.Clear();detail.Content=null;}
}
